        self.turn_started = Some(Instant::now());
        self.activity = None;
        let id = format!("t{}", self.turn_seq);
        self.pending = Some(id.clone());
        self.sent_prompt = Some((id.clone(), text.clone()));
        Some(Action::Send(Command::PromptSubmit { id, text }))
    }

